### 💻 Código Fuente Clave

#### 1. Archivo de Reescritura Apache (`api/.htaccess`)
```apache
# Desactivar la negociación automática de contenido de Apache
Options -MultiViews

# Activar motor de reescritura de URLs
RewriteEngine On

# Regla 1: Captura de un socio específico por ID numérico en la URL
RewriteRule ^socios/([0-9]+)/?$ socios.php?id=$1 [L,QSA]

# Regla 2: Petición a la colección general de socios
RewriteRule ^socios/?$ socios.php [L,QSA]
```

#### 2. Controlador REST de Socios (`api/socios.php`)
```php
<?php
header('Content-Type: application/json; charset=utf-8');
require_once '../conexion.php';

$metodo = $_SERVER['REQUEST_METHOD'];

if ($metodo === 'GET') {
    $id = $_GET['id'] ?? null;
    if ($id && filter_var($id, FILTER_VALIDATE_INT)) {
        $stmt = $conexion->prepare("SELECT * FROM socio WHERE id_socio = :id");
        $stmt->execute(['id' => $id]);
        $socio = $stmt->fetch();
        if ($socio) {
            echo json_encode($socio, JSON_UNESCAPED_UNICODE);
        } else {
            http_response_code(404);
            echo json_encode(["error" => "Socio no encontrado"]);
        }
    } else {
        $socios = $conexion->query("SELECT * FROM socio")->fetchAll();
        echo json_encode($socios, JSON_UNESCAPED_UNICODE);
    }
}
elseif ($metodo === 'POST') {
    // Lectura del cuerpo de la petición (Body JSON)
    $json = file_get_contents('php://input');
    $datos = json_decode($json, true);

    if (empty($datos['nombre']) || empty($datos['dni'])) {
        http_response_code(400);
        echo json_encode(["error" => "Faltan datos obligatorios"]);
        exit;
    }

    $sql = "INSERT INTO socio (nombre, apellido1, dni, fecha_alta, estado) 
            VALUES (:nom, :ape, :dni, NOW(), 'Activo')";
    $stmt = $conexion->prepare($sql);
    $stmt->execute([
        'nom' => trim($datos['nombre']),
        'ape' => trim($datos['apellido1']),
        'dni' => trim($datos['dni'])
    ]);

    http_response_code(201);
    echo json_encode([
        "mensaje" => "Socio registrado con éxito",
        "id_socio" => $conexion->lastInsertId()
    ], JSON_UNESCAPED_UNICODE);
}
elseif ($metodo === 'PUT') {
    $id = $_GET['id'] ?? null;
    $datos = json_decode(file_get_contents('php://input'), true);

    $sql = "UPDATE socio SET nombre = :nom, apellido1 = :ape WHERE id_socio = :id";
    $stmt = $conexion->prepare($sql);
    $stmt->execute([
        'nom' => trim($datos['nombre']),
        'ape' => trim($datos['apellido1']),
        'id' => $id
    ]);

    http_response_code(200);
    echo json_encode(["mensaje" => "Socio actualizado correctamente"], JSON_UNESCAPED_UNICODE);
}
?>
```

